import csv
import io


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    stream = io.StringIO(raw_csv, newline="")
    try:
        rows = list(csv.reader(
            stream,
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=True,
            strict=False,
        ))
    except csv.Error:
        rows = []
        current_row = []
        current_field = []
        in_quotes = False
        i = 0

        while i < len(raw_csv):
            char = raw_csv[i]

            if in_quotes:
                if char == '"':
                    if i + 1 < len(raw_csv) and raw_csv[i + 1] == '"':
                        current_field.append('"')
                        i += 2
                        continue
                    in_quotes = False
                else:
                    current_field.append(char)
                i += 1
                continue

            if char == '"' and not current_field:
                in_quotes = True
                i += 1
            elif char == ",":
                current_row.append("".join(current_field))
                current_field = []
                i += 1
                while i < len(raw_csv) and raw_csv[i] == " ":
                    i += 1
            elif char == "\r" or char == "\n":
                current_row.append("".join(current_field))
                current_field = []
                rows.append(current_row)
                current_row = []
                if char == "\r" and i + 1 < len(raw_csv) and raw_csv[i + 1] == "\n":
                    i += 2
                else:
                    i += 1
            else:
                current_field.append(char)
                i += 1

        if current_field or current_row or (
            raw_csv and raw_csv[-1] not in "\r\n"
        ):
            current_row.append("".join(current_field))
            rows.append(current_row)

    while rows and not rows[0]:
        rows.pop(0)

    if rows and len(rows[0]) == 1:
        directive = rows[0][0].strip().lower()
        if directive.startswith("sep=") and len(directive) == 5:
            rows.pop(0)

    if not rows:
        return {"columns": [], "rows": []}

    width = max((len(row) for row in rows), default=0)
    if width == 0:
        return {"columns": [], "rows": rows}

    normalized_rows = [
        list(row) + [""] * (width - len(row))
        for row in rows
    ]
    columns = ["column_" + str(index + 1) for index in range(width)]
    return {"columns": columns, "rows": normalized_rows}
